    incomingSegmentsFileName =
        IndexFileNames.fileNameFromGeneration(
            IndexFileNames.SEGMENTS, "", incomingLastGeneration);
    incomingPendingFileName =
        IndexFileNames.fileNameFromGeneration(
            IndexFileNames.PENDING_SEGMENTS, "", incomingLastGeneration);
