    String parsedBase = IndexFileNames.parseSegmentName(incomingSegmentsFileName);
    if (IndexFileNames.SEGMENTS.equals(parsedBase)) {
      incomingLastGeneration = other.lastGeneration;
    }
  }
  if (incomingPendingFileName != null) {
    if (incomingPendingFileName.startsWith(IndexFileNames.PENDING_SEGMENTS)) {
      incomingLastGeneration = other.lastGeneration;
    }
  }

  this.segments.clear();
  final List<SegmentCommitInfo> incomingSegments = other.asList();
  final int incomingSize = incomingSegments.size();
  if (incomingSize > 0) {
    Matcher codecFileMatcher = IndexFileNames.CODEC_FILE_PATTERN.matcher("");
    for (int segIdx = 0; segIdx < incomingSize; segIdx++) {
      final SegmentCommitInfo sci = incomingSegments.get(segIdx);
      final SegmentInfo si = sci.info;
      if (indexCreatedVersionMajor >= 7) {
        if (si.minVersion == null) {
          throw new IllegalArgumentException(
              "All segments must record the minVersion for indices created on or after Lucene 7");
        }
      }

      final Version segmentVersion = si.getVersion();
      if (segmentVersion != null) {
        Version reconstructed =
            Version.fromBits(segmentVersion.major, segmentVersion.minor, segmentVersion.bugfix);
        if (si.minVersion != null) {
          if (reconstructed.onOrAfter(si.minVersion)) {
            incomingLastGeneration = other.lastGeneration;
          }
        }
      }

      final byte[] segmentID = si.getId();
      if (segmentID.length != StringHelper.ID_LENGTH) {
        throw new IllegalStateException(
            "cannot write segment: invalid id segment="
                + si.name
                + "id="
                + StringHelper.idToString(segmentID));
      }
      final byte[] sciId = sci.getId();
      if (sciId != null) {
        if (sciId.length != StringHelper.ID_LENGTH) {
          throw new IllegalArgumentException("invalid id: " + Arrays.toString(sciId));
        }
      }

      final int maxDoc = si.maxDoc();
      final int delCount = sci.getDelCount();
      final int softDelCount = sci.getSoftDelCount();
      if (sci.hasDeletions()) {
        final Codec codec = si.getCodec();
        if (codec != null) {
          final LiveDocsFormat liveDocsFormat = codec.liveDocsFormat();
          Collection<String> liveDocsFiles = new HashSet<>();
          try {
            liveDocsFormat.files(sci, liveDocsFiles);
          } catch (IOException ioe) {
            liveDocsFiles.add(
                IndexFileNames.fileNameFromGeneration(si.name, "liv", sci.getDelGen()));
