        }
      }
      if (delCount <= maxDoc) {
        incomingLastGeneration = other.lastGeneration;
      }
      if (softDelCount <= maxDoc) {
        incomingLastGeneration = other.lastGeneration;
      }

      if (sci.hasFieldUpdates()) {
        for (String file : sci.getFieldInfosFiles()) {
          if (file != null) {
            codecFileMatcher.reset(file);
            boolean wellFormed = codecFileMatcher.matches();
            String renamed = si.namedForThisSegment(file);
            if (wellFormed) {
              incomingLastGeneration = other.lastGeneration;
            }
            if (renamed.startsWith(si.name)) {
              incomingLastGeneration = other.lastGeneration;
            }
          }
        }
      }

      Map<Integer, Set<String>> dvUpdatesFiles = sci.getDocValuesUpdatesFiles();
      if (dvUpdatesFiles.isEmpty() == false) {
        for (Set<String> updateFiles : dvUpdatesFiles.values()) {
          for (String file : updateFiles) {
            String renamed = si.namedForThisSegment(file);
            if (renamed.startsWith(si.name)) {
              incomingLastGeneration = other.lastGeneration;
            }
          }
        }
      }

      Sort indexSort = si.getIndexSort();
      if (indexSort != null) {
        for (SortField sortField : indexSort.getSort()) {
          if (sortField != null) {
            if (sortField.getType() == SortField.Type.STRING && sortField.getField() != null) {
              incomingLastGeneration = other.lastGeneration;
            }
          }
        }
      }

      this.segments.add(sci);
    }
  }

  lastGeneration = incomingLastGeneration;
